#include <bits/stdc++.h>
using namespace std;
// input: n m, then v[0..n-1], then d[0..n-1]
int main(){
    int n; long long m; cin >> n >> m;
    vector<long long> v(n), d(n);
    for (auto &x : v) cin >> x;
    for (auto &x : d) cin >> x;
    priority_queue<pair<long long,int>> pq;          // (current value, item)
    for (int i = 0; i < n; i++) if (v[i] > 0) pq.push({v[i], i});
    long long total = 0;
    while (m-- > 0 && !pq.empty()) {
        auto [val, i] = pq.top(); pq.pop();
        total += val;
        if (val - d[i] > 0) pq.push({val - d[i], i}); // next purchase of same item
    }
    cout << total << "\n";
}

