#include <bits/stdc++.h>
using namespace std;
long long candies(const vector<int>& r){
    int n = r.size();
    vector<long long> c(n, 1);
    for (int i = 1; i < n; i++) if (r[i] > r[i-1]) c[i] = c[i-1] + 1;
    for (int i = n - 2; i >= 0; i--) if (r[i] > r[i+1]) c[i] = max(c[i], c[i+1] + 1);
    return accumulate(c.begin(), c.end(), 0LL);
}
int main(){
    int n; cin >> n; vector<int> r(n);
    for (auto &x : r) cin >> x;
    cout << candies(r) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
long long cost(const string& s, char ch){
    vector<long long> q;
    for (int i = 0, k = 0; i < (int)s.size(); i++)
        if (s[i] == ch) { q.push_back(i - k); k++; }
    if (q.empty()) return 0;
    long long med = q[q.size() / 2], r = 0;
    for (long long x : q) r += llabs(x - med);
    return r;
}
int main(){
    string s; cin >> s;
    cout << min(cost(s, '1'), cost(s, '0')) << "\n";   // use cost(s,'1') if only 1s must be grouped
}

#include <bits/stdc++.h>
using namespace std;
int longestSubseq(const string& s, long long K){
    long long val = 0; int len = 0;
    for (int i = (int)s.size() - 1; i >= 0; i--) {
        if (s[i] == '0') len++;
        else if (len < 31 && val + (1LL << len) <= K) { val += 1LL << len; len++; }
    }
    return len;
}
int main(){ string s; long long k; cin >> s >> k; cout << longestSubseq(s, k) << "\n"; }

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; long long k; cin >> n >> k;
    vector<long long> A(n);
    for (auto &x : A) cin >> x;
    if (k == 0) { cout << A[0]; return 0; }
    if (n == 1) { cout << -1; return 0; }          // no move possible
    long long pref = A[0], best = LLONG_MIN, ans = LLONG_MIN;
    for (long long t = 1; t <= min<long long>(k, n - 1); t++) {
        pref += A[t];
        best = max(best, A[t-1] + A[t]);
        long long rem = k - t;
        ans = max(ans, pref + (rem / 2) * best + (rem % 2 ? A[t-1] : 0));
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, k; cin >> n >> k;
    vector<long long> s(n); vector<int> c(k);
    for (auto &x : s) cin >> x;
    for (auto &x : c) cin >> x;
    sort(s.begin(), s.end()); sort(c.begin(), c.end());
    long long ans = 0; int hi = n - 1;
    for (int i = 0; i < k; i++) {          // maxima, size-1 groups first
        ans += s[hi];
        if (c[i] == 1) ans += s[hi];
        hi--;
    }
    int lo = 0;
    for (int i = k - 1; i >= 0; i--) {     // minima, biggest groups first
        if (c[i] == 1) continue;
        ans += s[lo];
        lo += c[i] - 1;
    }
    cout << ans << "\n";
}

