#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, K; cin >> n >> K;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    set<pair<long long,int>> w;                 // (value, -index): ties -> rightmost first
    for (int j = 1; j <= K && j < n; j++) w.insert({a[j], -j});
    for (int i = 0; i < n; i++) {
        if (!w.empty() && w.begin()->first < a[i]) {
            swap(a[i], a[-w.begin()->second]);
            break;
        }
        if (i + 1 < n) w.erase({a[i+1], -(i+1)});
        if (i + 1 + K < n) w.insert({a[i+1+K], -(i+1+K)});
    }
    for (int i = 0; i < n; i++) cout << a[i] << " \n"[i == n-1];
}

