int main(){
    int n; cin >> n;
    map<long long,int> cnt;
    for (int i = 0; i < n; i++) { long long x; cin >> x; cnt[x]++; }
    vector<long long> f;
    for (auto &p : cnt) f.push_back(p.second);
    sort(f.begin(), f.end());
    long long best = 0;
    for (long long x = 1; x <= f.back(); x++) {
        long long cur = x, tot = 0;
        auto it = f.begin();
        while (true) {
            it = lower_bound(it, f.end(), cur);
            if (it == f.end()) break;
            tot += cur; ++it; cur *= 2;
        }
        best = max(best, tot);
    }
    cout << best << "\n";
}

