#include <bits/stdc++.h>
using namespace std;
int N, M; long long H; vector<long long> V;
bool ok(int s){
    long long hp = H, heroes = M;
    for (int i = s; i < N; i++) {
        long long v = V[i];
        while (v > 0) {
            if (heroes == 0) return false;
            if (hp > v) { hp -= v; v = 0; }
            else if (hp == v) { v = 0; heroes--; hp = H; }
            else { v -= hp; heroes--; hp = H; }
        }
    }
    return true;
}
int main(){
    cin >> N >> M >> H; V.resize(N);
    for (auto &x : V) cin >> x;
    int lo = 0, hi = N;
    while (lo < hi) { int mid = (lo + hi) / 2; if (ok(mid)) hi = mid; else lo = mid + 1; }
    cout << lo << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, K, D; cin >> n >> K >> D;
    vector<long long> a(n); for (auto &x : a) cin >> x;
    const long long INF = LLONG_MAX; int R = min(D, n);
    vector<long long> cm(R, INF);
    for (int i = 0; i < n; i++) cm[i % D] = min(cm[i % D], a[i]);
    int b1 = -1, b2 = -1;                              // two smallest class minima
    for (int r = 0; r < R; r++) {
        if (b1 < 0 || cm[r] < cm[b1]) { b2 = b1; b1 = r; }
        else if (b2 < 0 || cm[r] < cm[b2]) b2 = r;
    }
    long long best = INF;
    for (int r = 0; r < R; r++) {
        vector<long long> c; for (int i = r; i < n; i += D) c.push_back(a[i]);
        int m = c.size(); if (m < K) continue;
        vector<long long> pre(m + 1, 0), pm(m + 1, INF), sm(m + 1, INF);
        for (int i = 0; i < m; i++) { pre[i+1] = pre[i] + c[i]; pm[i+1] = min(pm[i], c[i]); }
        for (int i = m - 1; i >= 0; i--) sm[i] = min(sm[i+1], c[i]);
        long long other = (r == b1) ? (b2 < 0 ? INF : cm[b2]) : cm[b1];
        deque<int> dq;
        for (int i = 0; i < m; i++) {
            while (!dq.empty() && c[dq.back()] <= c[i]) dq.pop_back();
            dq.push_back(i);
            if (dq.front() <= i - K) dq.pop_front();
            if (i < K - 1) continue;
            int t = i - K + 1;
            long long sum = pre[i+1] - pre[t], mx = c[dq.front()];
            long long mn = min({other, pm[t], sm[i+1]});
            best = min(best, mn < mx ? sum - mx + mn : sum);
        }
    }
    cout << (best == INF ? -1 : best) << "\n";
}
